function UIActionPointDropRewardNode:RefreshNode(data, type, index)
    -- print("[歼灭战]", index, table.dump(data, nil, 3))

    local rewardList = data

    self.SImg_Line.Status = index
    self.SImg_Bg.Status = index

    -- 实时匹配奖励的专属特效
    local tf = self.controller.gameObject.transform:Find("UIFX_frameglow")
    if isNotNull(tf) then
        KTool.SetActive(tf, checkNumber(type) == Constants.RewardSourceType.Realtime)
    end
    
    local name = GoodsUtils.GetRewardSourceDesc(type)
    self.Txt_RewardType.text = name
    
    for i, rewardData in ipairs(rewardList) do
        local go = self:GetGoodNode(i)
        local goodNode = go.transform:GetChild(0).gameObject
        local LT_GoodNode = GetLuaBehaviour(goodNode, GoodNodeLuaPath).Env

        local params
        local idType = GoodsUtils.GetIdType(rewardData.id)
        if idType == Constants.IDType.Equipment 
        or idType == Constants.IDType.EquipmentCore then 
            -- 装备
            params = { 
                goodsId = rewardData.id, 
                text = tostring(rewardData.num), 
                dojo = rewardData.playerEquipment, 
                -- superScript = rewardData.type 
            }
        else
            -- 道具
            params = { 
                goodsId = rewardData.id, 
                isShowNo = true, 
                text = string.format("x%s", checkInt(math.abs(rewardData.num))), 
                dojo = rewardData.playerEquipment, 
                -- superScript = rewardData.type 
            }
        end

        LT_GoodNode:Reload(params)
        LT_GoodNode:SetClickButtonAction(function(goodsId, uId)
            GameUtils.ShowResultTips(goodNode.transform:Find("Container"), goodsId, uId)
        end)
    end
end

--- 获取一个node,不存在就创建一个
---@param index any
function UIActionPointDropRewardNode:GetGoodNode(index)
    local goName = "GoodPar"..tostring(index)
    local TF_Go = self.controller.transform:Find(goName)
    if isNotNull(TF_Go) then
        KTool.SetActive(TF_Go, true)
        return TF_Go.gameObject
    else
        local go = CfUtils.InstantiateGo(self.RT_GoodNode, self.controller.transform)
        go.name = goName
        KTool.SetActive(TF_Go, true)
        return go
    end
end

--- 把没在使用中的node关闭掉
---@param inUseCount number 正在使用中的node数量
function UIActionPointDropRewardNode:DeactiveNoUseRewardNode(inUseCount)
    local count = 1
    while true do
        local index = inUseCount + count
        local tf = self.controller.transform:Find("GoodPar"..tostring(index))
        if isNull(tf) then
            break
        else
            count = count + 1
            KTool.SetActive(tf, false)
        end
    end
end

return UIActionPointDropRewardNode